1	/**
2	 * Auto-Apply Pipeline
3	 * 
4	 * When auto-apply mode is enabled, this pipeline:
5	 * 1. Takes violations found by the scanner
6	 * 2. Generates rewrites via Claude (same as auto-rewrite-pipeline)
7	 * 3. Applies the fix directly to the source file
8	 * 4. Logs the full before/after diff to the audit log
9	 * 5. Notifies the owner of what was changed
10	 * 
11	 * SAFETY RAILS:
12	 * - Only applies to Standard and Enterprise profiles (not Regulated/High-sensitivity)
13	 * - Only applies patches up to the configured max severity (default: medium)
14	 * - Critical violations ALWAYS require manual approval regardless of mode
15	 * - Every auto-applied patch is logged with full diff to governance_audit_log
16	 * - Profile lock mode disables auto-apply
17	 * - Dry-run mode available for testing
18	 */
19	
20	import * as fs from 'fs';
21	import * as path from 'path';
22	import { drizzle } from 'drizzle-orm/postgres-js';
23	// D-120: shared singleton (was per-call drizzle() — Supabase pool exhaustion).
24	import { sharedDrizzleDb } from '../_core/db-singleton';
25	import { eq } from 'drizzle-orm';
26	import { governanceSettings, governanceAuditLog, proposedPatches, buildGateLog } from '../../drizzle/schema';
27	import { generateRewrite, processViolation, type ViolationInput, type PatchProposal } from './auto-rewrite-pipeline';
28	import { notifyOwner } from '../_core/notification';
29	import { getGravitoMCPServer } from '../agent/mcp/gravito-mcp-server';
30	import { calculateCorrectionConfidence, type CorrectionConfidence } from '../governance/governance-persistence';
31	import { generalLog } from '../_core/logger';
32	
33	function getDb() {
34	  return sharedDrizzleDb();
35	}
36	
37	// ============================================================================
38	// TYPES
39	// ============================================================================
40	
41	export interface AutoApplyConfig {
42	  enabled: boolean;
43	  maxSeverity: 'low' | 'medium' | 'high' | 'critical';
44	  activeProfile: string;
45	  profileLocked: boolean;
46	}
47	
48	/**
49	 * Confidence-gated auto-apply decision.
50	 * Maps correction confidence → autonomy level:
51	 *   auto-fix:     confidence >= 80 → full autonomy
52	 *   review-first: confidence 50-79 → queue for human review
53	 *   manual-only:  confidence < 50  → block auto-apply entirely
54	 */
55	export interface ConfidenceGateResult {
56	  allowed: boolean;
57	  recommendation: CorrectionConfidence['recommendation'];
58	  confidenceScore: number;
59	  reason: string;
60	}
61	
62	export interface AutoApplyResult {
63	  violation: ViolationInput;
64	  action: 'auto_applied' | 'queued_for_review' | 'skipped' | 'failed' | 'buildgate_blocked' | 'confidence_gated';
65	  reason: string;
66	  patchId?: number;
67	  filePath?: string;
68	  diff?: { before: string; after: string };
69	  buildGateRunId?: string;
70	  confidenceGate?: ConfidenceGateResult;
71	}
72	
73	// ============================================================================
74	// BUILD GATE PREFLIGHT — Mandatory architecture + truth check before any rewrite
75	// ============================================================================
76	
77	/**
78	 * Run buildGate preflight check on a proposed rewrite.
79	 * This ensures every auto-generated patch passes architecture + truth validation
80	 * BEFORE the rewrite is generated, not after.
81	 *
82	 * If buildGate returns 'block' or 'modify', the patch is moved to manual review.
83	 */
84	async function runBuildGatePreflight(
85	  violation: ViolationInput,
86	): Promise<{ passed: boolean; decision: string; reason: string; runId: string }> {
87	  try {
88	    const server = getGravitoMCPServer();
89	    const result = await server.buildGate({
90	      proposed_action: 'rewrite_content',
91	      description: `Auto-rewrite for ${violation.violationType} violation on ${violation.route}: ${violation.violationDetails}`,
92	      target_module: violation.route,
93	      claims_in_content: [violation.originalContent],
94	    });
95	
96	    // Log the buildGate decision
97	    try {
98	      const db = getDb();
99	      await db!.insert(buildGateLog).values({
100	        runId: result.gravito_run_id,
101	        proposedAction: 'rewrite_content',
102	        description: `Auto-rewrite for ${violation.violationType} on ${violation.route}`,
103	        targetModule: violation.route,
104	        decision: result.decision,
105	        reason: result.reason,
106	        truthViolations: JSON.stringify(result.truth_violations),
107	        architectureConflicts: JSON.stringify(result.architecture_conflicts),
108	        existingTools: JSON.stringify(result.existing_tools),
109	        existingModules: JSON.stringify(result.existing_modules),
110	        callerContext: 'auto-apply',
111	      });
112	    } catch (logError) {
113	      generalLog.warn('[BuildGate] Failed to log decision:', logError);
114	    }
115	
116	    if (result.decision === 'proceed') {
117	      generalLog.info(`[BuildGate] ✅ PROCEED for rewrite on ${violation.route} (${result.gravito_run_id})`);
118	      return { passed: true, decision: result.decision, reason: result.reason, runId: result.gravito_run_id };
119	    } else {
120	      generalLog.info(`[BuildGate] ⛔ ${result.decision.toUpperCase()} for rewrite on ${violation.route}: ${result.reason} (${result.gravito_run_id})`);
121	      return { passed: false, decision: result.decision, reason: result.reason, runId: result.gravito_run_id };
122	    }
123	  } catch (error) {
124	    // BuildGate failure = fail-closed: block the rewrite
125	    const errorMsg = error instanceof Error ? error.message : String(error);
126	    generalLog.error(`[BuildGate] ERROR for ${violation.route}: ${errorMsg} — failing closed (blocking rewrite)`);
127	    return {
128	      passed: false,
129	      decision: 'block',
130	      reason: `BuildGate preflight error: ${errorMsg}`,
131	      runId: `bg_error_${Date.now()}`,
132	    };
133	  }
134	}
135	
136	// Severity ordering for comparison
137	const SEVERITY_ORDER: Record<string, number> = {
138	  'low': 1,
139	  'medium': 2,
140	  'high': 3,
141	  'critical': 4,
142	};
143	
144	// ============================================================================
145	// CONFIGURATION
146	// ============================================================================
147	
148	/**
149	 * Load auto-apply configuration from the database.
150	 */
151	export async function getAutoApplyConfig(): Promise<AutoApplyConfig> {
152	  try {
153	    const db = getDb();
154	    const rows = await db!.select().from(governanceSettings).limit(1);
155	    
156	    if (rows.length === 0) {
157	      return {
158	        enabled: false,
159	        maxSeverity: 'medium',
160	        activeProfile: 'Enterprise',
161	        profileLocked: false,
162	      };
163	    }
164	
165	    const settings = rows[0];
166	    return {
167	      enabled: settings.autoApplyMode ?? false,
168	      maxSeverity: (settings.autoApplyMaxSeverity as unknown) ?? 'medium',
169	      activeProfile: settings.activeProfile,
170	      profileLocked: settings.profileLocked,
171	    };
172	  } catch (error) {
173	    generalLog.error('[AutoApply] Failed to load config:', error);
174	    return {
175	      enabled: false,
176	      maxSeverity: 'medium',
177	      activeProfile: 'Enterprise',
178	      profileLocked: false,
179	    };
180	  }
181	}
182	
183	/**
184	 * Update auto-apply settings in the database.
185	 */
186	export async function setAutoApplyMode(
187	  enabled: boolean,
188	  maxSeverity?: 'low' | 'medium' | 'high' | 'critical',
189	  actor?: string,
190	): Promise<void> {
191	  const db = getDb();
192	  const rows = await db!.select().from(governanceSettings).limit(1);
193	
194	  const updateData: any = {
195	    autoApplyMode: enabled,
196	    lastUpdatedBy: actor || 'system',
197	    lastUpdatedAt: new Date(),
198	  };
199	  if (maxSeverity) {
200	    updateData.autoApplyMaxSeverity = maxSeverity;
201	  }
202	
203	  if (rows.length === 0) {
204	    await db!.insert(governanceSettings).values({
205	      ...updateData,
206	      activeProfile: 'Enterprise',
207	    });
208	  } else {
209	    await db!.update(governanceSettings)
210	      .set(updateData)
211	      .where(eq(governanceSettings.id, rows[0].id));
212	  }
213	
214	  // Audit log
215	  await db!.insert(governanceAuditLog).values({
216	    action: 'profile_change' as const,
217	    actor: actor || 'system',
218	    reason: `Auto-apply mode ${enabled ? 'ENABLED' : 'DISABLED'}${maxSeverity ? ` (max severity: ${maxSeverity})` : ''}`,
219	    metadata: JSON.stringify({ autoApplyMode: enabled, maxSeverity }),
220	  });
221	
222	  generalLog.info(`[AutoApply] Mode ${enabled ? 'ENABLED' : 'DISABLED'} by ${actor || 'system'}`);
223	}
224	
225	// ============================================================================
226	// SAFETY CHECKS
227	// ============================================================================
228	
229	/**
230	 * Determine if a violation can be auto-applied based on current config.
231	 * Static safety checks only — does not consult historical confidence.
232	 */
233	function canAutoApplyStatic(
234	  violation: ViolationInput,
235	  config: AutoApplyConfig,
236	): { allowed: boolean; reason: string } {
237	  // Check 1: Auto-apply must be enabled
238	  if (!config.enabled) {
239	    return { allowed: false, reason: 'Auto-apply mode is disabled' };
240	  }
241	
242	  // Check 2: Profile lock disables auto-apply
243	  if (config.profileLocked) {
244	    return { allowed: false, reason: 'Profile is locked — auto-apply disabled during lock' };
245	  }
246	
247	  // Check 3: Only Standard and Enterprise profiles allow auto-apply
248	  if (!['Standard', 'Enterprise'].includes(config.activeProfile)) {
249	    return { allowed: false, reason: `Auto-apply not allowed for ${config.activeProfile} profile (requires manual approval)` };
250	  }
251	
252	  // Check 4: Critical violations ALWAYS require manual approval
253	  if (violation.severity === 'critical') {
254	    return { allowed: false, reason: 'Critical violations always require manual approval' };
255	  }
256	
257	  // Check 5: Severity must be within configured max
258	  const violationLevel = SEVERITY_ORDER[violation.severity] || 0;
259	  const maxLevel = SEVERITY_ORDER[config.maxSeverity] || 2;
260	  if (violationLevel > maxLevel) {
261	    return { allowed: false, reason: `Violation severity ${violation.severity} exceeds auto-apply max ${config.maxSeverity}` };
262	  }
263	
264	  return { allowed: true, reason: 'Passed all static safety checks' };
265	}
266	
267	/**
268	 * Check correction confidence for a route — adaptive autonomy gating.
269	 * 
270	 * This is the key innovation: instead of a global on/off for auto-apply,
271	 * each route gets its own autonomy level based on historical fix patterns.
272	 * 
273	 * Routes where fixes reliably stick → auto-fix allowed
274	 * Routes where fixes sometimes revert → queue for human review
275	 * Routes where fixes frequently fail → block auto-apply entirely
276	 * 
277	 * Falls back gracefully: if confidence data is unavailable, allows
278	 * auto-apply (the static checks already passed).
279	 */
280	async function checkCorrectionConfidenceGate(
281	  route: string,
282	): Promise<ConfidenceGateResult> {
283	  try {
284	    const confidence = await calculateCorrectionConfidence(route);
285	    
286	    // No correction history yet → allow (benefit of the doubt)
287	    if (confidence.totalCorrections === 0) {
288	      return {
289	        allowed: true,
290	        recommendation: 'review-first',
291	        confidenceScore: confidence.confidenceScore,
292	        reason: `No correction history for ${route} — allowing with default confidence`,
293	      };
294	    }
295	    
296	    switch (confidence.recommendation) {
297	      case 'auto-fix':
298	        return {
299	          allowed: true,
300	          recommendation: 'auto-fix',
301	          confidenceScore: confidence.confidenceScore,
302	          reason: `High correction confidence (${confidence.confidenceScore}/100) — ${confidence.successfulCorrections}/${confidence.totalCorrections} fixes stuck`,
303	        };
304	      
305	      case 'review-first':
306	        return {
307	          allowed: false,
308	          recommendation: 'review-first',
309	          confidenceScore: confidence.confidenceScore,
310	          reason: `Medium correction confidence (${confidence.confidenceScore}/100) — ${confidence.revertedCorrections}/${confidence.totalCorrections} fixes reverted. Routing to manual review.`,
311	        };
312	      
313	      case 'manual-only':
314	        return {
315	          allowed: false,
316	          recommendation: 'manual-only',
317	          confidenceScore: confidence.confidenceScore,
318	          reason: `Low correction confidence (${confidence.confidenceScore}/100) — fixes frequently revert on ${route}. Auto-apply blocked.`,
319	        };
320	      
321	      default:
322	        return {
323	          allowed: true,
324	          recommendation: 'review-first',
325	          confidenceScore: confidence.confidenceScore,
326	          reason: 'Unknown recommendation — allowing with caution',
327	        };
328	    }
329	  } catch (err) {
330	    // Confidence check failed — graceful degradation: allow auto-apply
331	    generalLog.warn(`[AutoApply] Correction confidence check failed for ${route}:`, err);
332	    return {
333	      allowed: true,
334	      recommendation: 'review-first',
335	      confidenceScore: 50,
336	      reason: 'Correction confidence unavailable — allowing with default (graceful degradation)',
337	    };
338	  }
339	}
340	
341	/**
342	 * Combined auto-apply decision: static checks + confidence gating.
343	 * 
344	 * Two-layer safety:
345	 * 1. Static checks (config, profile, severity) — fast, deterministic
346	 * 2. Confidence gate (historical patterns) — adaptive, per-route
347	 * 
348	 * Both must pass for auto-apply to proceed.
349	 */
350	async function canAutoApply(
351	  violation: ViolationInput,
352	  config: AutoApplyConfig,
353	): Promise<{ allowed: boolean; reason: string; confidenceGate?: ConfidenceGateResult }> {
354	  // Layer 1: Static safety checks
355	  const staticResult = canAutoApplyStatic(violation, config);
356	  if (!staticResult.allowed) {
357	    return { allowed: false, reason: staticResult.reason };
358	  }
359	  
360	  // Layer 2: Correction confidence gating (adaptive autonomy)
361	  const confidenceGate = await checkCorrectionConfidenceGate(violation.route);
362	  
363	  if (!confidenceGate.allowed) {
364	    generalLog.info(`[AutoApply] ${violation.route}: Static checks passed but confidence gate blocked — ${confidenceGate.reason}`);
365	    return {
366	      allowed: false,
367	      reason: `Confidence gate: ${confidenceGate.reason}`,
368	      confidenceGate,
369	    };
370	  }
371	  
372	  generalLog.info(`[AutoApply] ${violation.route}: All checks passed (confidence: ${confidenceGate.confidenceScore}/100, recommendation: ${confidenceGate.recommendation})`);
373	  return {
374	    allowed: true,
375	    reason: `${staticResult.reason} + ${confidenceGate.reason}`,
376	    confidenceGate,
377	  };
378	}
379	
380	// ============================================================================
381	// SOURCE FILE MAPPING
382	// ============================================================================
383	
384	const ROUTE_TO_FILE: Record<string, string> = {
385	  '/': 'client/src/pages/Home.tsx',
386	  '/products': 'client/src/pages/Products.tsx',
387	  '/pricing': 'client/src/pages/Pricing.tsx',
388	  '/products/flux': 'client/src/pages/products/Flux.tsx',
389	  '/products/sentinel': 'client/src/pages/products/Sentinel.tsx',
390	  '/products/conduit': 'client/src/pages/products/Conduit.tsx',
391	  '/products/deploy': 'client/src/pages/products/Deploy.tsx',
392	  '/products/certify': 'client/src/pages/products/Certify.tsx',
393	  '/for-cto': 'client/src/pages/ForCTO.tsx',
394	  '/for-cs-director': 'client/src/pages/ForCSDirector.tsx',
395	  '/for-ceo': 'client/src/pages/ForCEO.tsx',
396	  '/healthcare': 'client/src/pages/Healthcare.tsx',
397	  '/finance': 'client/src/pages/Finance.tsx',
398	  '/trust': 'client/src/pages/Trust.tsx',
399	  '/security': 'client/src/pages/Security.tsx',
400	  '/proof': 'client/src/pages/ProofArtifacts.tsx',
401	};
402	
403	/**
404	 * Apply a rewrite to the actual source file.
405	 * Returns the file path and before/after diff.
406	 */
407	function applyToSourceFile(
408	  route: string,
409	  originalContent: string,
410	  proposedContent: string,
411	): { success: boolean; filePath: string; before: string; after: string; error?: string } {
412	  const relativeFile = ROUTE_TO_FILE[route];
413	  if (!relativeFile) {
414	    return {
415	      success: false,
416	      filePath: '',
417	      before: '',
418	      after: '',
419	      error: `No source file mapping for route ${route}`,
420	    };
421	  }
422	
423	  const projectRoot = path.resolve(process.cwd());
424	  const filePath = path.join(projectRoot, relativeFile);
425	
426	  if (!fs.existsSync(filePath)) {
427	    return {
428	      success: false,
429	      filePath: relativeFile,
430	      before: '',
431	      after: '',
432	      error: `Source file not found: ${relativeFile}`,
433	    };
434	  }
435	
436	  const fileContent = fs.readFileSync(filePath, 'utf-8');
437	
438	  // Find the original content in the file (fuzzy match — content may be extracted/transformed)
439	  // We look for the longest substring match
440	  const normalizedOriginal = originalContent.trim().replace(/\s+/g, ' ');
441	  const normalizedFile = fileContent.replace(/\s+/g, ' ');
442	
443	  // Try exact match first
444	  if (fileContent.includes(originalContent.trim())) {
445	    const newContent = fileContent.replace(originalContent.trim(), proposedContent.trim());
446	    fs.writeFileSync(filePath, newContent, 'utf-8');
447	    return {
448	      success: true,
449	      filePath: relativeFile,
450	      before: originalContent.trim(),
451	      after: proposedContent.trim(),
452	    };
453	  }
454	
455	  // Try normalized match (whitespace-insensitive)
456	  if (normalizedFile.includes(normalizedOriginal)) {
457	    // Find the actual position in the original file
458	    const startIdx = normalizedFile.indexOf(normalizedOriginal);
459	    // Map back to original file positions (approximate)
460	    let charCount = 0;
461	    let realStart = 0;
462	    for (let i = 0; i < fileContent.length; i++) {
463	      if (charCount === startIdx) {
464	        realStart = i;
465	        break;
466	      }
467	      charCount++;
468	      // Skip extra whitespace
469	      while (i + 1 < fileContent.length && /\s/.test(fileContent[i]) && /\s/.test(fileContent[i + 1])) {
470	        i++;
471	      }
472	    }
473	
474	    // For safety, log but don't apply fuzzy matches
475	    generalLog.warn(`[AutoApply] Fuzzy match found for ${route} but not applying (safety). Queuing for manual review.`);
476	    return {
477	      success: false,
478	      filePath: relativeFile,
479	      before: originalContent.trim(),
480	      after: proposedContent.trim(),
481	      error: 'Only exact matches are auto-applied. Fuzzy match found — queued for manual review.',
482	    };
483	  }
484	
485	  return {
486	    success: false,
487	    filePath: relativeFile,
488	    before: originalContent.trim(),
489	    after: proposedContent.trim(),
490	    error: 'Original content not found in source file. Content may have been extracted/transformed during scanning.',
491	  };
492	}
493	
494	// ============================================================================
495	// MAIN PIPELINE
496	// ============================================================================
497	
498	/**
499	 * Process a violation through the auto-apply pipeline.
500	 * 
501	 * If auto-apply is allowed: generate rewrite → apply to source → log audit
502	 * If not allowed: fall back to the standard approval queue
503	 */
504	export async function processViolationAutoApply(
505	  violation: ViolationInput,
506	  dryRun: boolean = false,
507	): Promise<AutoApplyResult> {
508	  const config = await getAutoApplyConfig();
509	  const safety = await canAutoApply(violation, config);
510	
511	  if (!safety.allowed) {
512	    // Determine if this was blocked by confidence gate vs static checks
513	    const isConfidenceGated = safety.confidenceGate && !safety.confidenceGate.allowed;
514	    const action = isConfidenceGated ? 'confidence_gated' as const : 'queued_for_review' as const;
515	    
516	    generalLog.info(`[AutoApply] ${violation.route}: ${safety.reason} — ${isConfidenceGated ? 'confidence-gated' : 'queuing'} for manual review`);
517	    try {
518	      const patchId = await processViolation(violation);
519	      return {
520	        violation,
521	        action,
522	        reason: safety.reason,
523	        patchId,
524	        confidenceGate: safety.confidenceGate,
525	      };
526	    } catch (error) {
527	      return {
528	        violation,
529	        action: 'failed',
530	        reason: `Queue failed: ${error instanceof Error ? error.message : String(error)}`,
531	        confidenceGate: safety.confidenceGate,
532	      };
533	    }
534	  }
535	
536	  // Auto-apply path
537	  generalLog.info(`[AutoApply] ${violation.route}: Running buildGate preflight for ${violation.violationType}`);
538	
539	  try {
540	    // 0. BUILD GATE PREFLIGHT — mandatory architecture + truth check
541	    const gateResult = await runBuildGatePreflight(violation);
542	    if (!gateResult.passed) {
543	      generalLog.info(`[AutoApply] ${violation.route}: BuildGate ${gateResult.decision} — ${gateResult.reason}. Moving to manual review.`);
544	      try {
545	        const patchId = await processViolation(violation);
546	        return {
547	          violation,
548	          action: 'buildgate_blocked',
549	          reason: `BuildGate ${gateResult.decision}: ${gateResult.reason}`,
550	          patchId,
551	          buildGateRunId: gateResult.runId,
552	        };
553	      } catch (queueError) {
554	        return {
555	          violation,
556	          action: 'buildgate_blocked',
557	          reason: `BuildGate ${gateResult.decision}: ${gateResult.reason} (queue also failed: ${queueError instanceof Error ? queueError.message : String(queueError)})`,
558	          buildGateRunId: gateResult.runId,
559	        };
560	      }
561	    }
562	
563	    generalLog.info(`[AutoApply] ${violation.route}: BuildGate passed (${gateResult.runId}). Generating rewrite for ${violation.violationType}`);
564	
565	    // 1. Generate rewrite
566	    const proposal = await generateRewrite(violation);
567	
568	    if (dryRun) {
569	      return {
570	        violation,
571	        action: 'skipped',
572	        reason: 'Dry run — rewrite generated but not applied',
573	        diff: { before: violation.originalContent, after: proposal.proposedContent },
574	      };
575	    }
576	
577	    // 2. Apply to source file
578	    const applyResult = applyToSourceFile(
579	      violation.route,
580	      violation.originalContent,
581	      proposal.proposedContent,
582	    );
583	
584	    if (!applyResult.success) {
585	      // Couldn't apply — fall back to queue
586	      generalLog.warn(`[AutoApply] ${violation.route}: Apply failed — ${applyResult.error}. Queuing for manual review.`);
587	      const patchId = await processViolation(violation);
588	      return {
589	        violation,
590	        action: 'queued_for_review',
591	        reason: `Auto-apply failed: ${applyResult.error}`,
592	        patchId,
593	        filePath: applyResult.filePath,
594	        diff: { before: applyResult.before, after: applyResult.after },
595	      };
596	    }
597	
598	    // 3. Store as applied patch
599	    const db = getDb();
600	    const [patchInserted] = await db!.insert(proposedPatches).values({
601	      scanId: violation.scanId,
602	      route: violation.route,
603	      violationType: violation.violationType,
604	      severity: violation.severity,
605	      originalContent: violation.originalContent,
606	      proposedContent: proposal.proposedContent,
607	      explanation: `[AUTO-APPLIED] ${proposal.explanation}`,
608	      status: 'applied',
609	      reviewedBy: 'auto-apply-pipeline',
610	      reviewedAt: new Date(),
611	      reviewNote: `Auto-applied by governance pipeline. File: ${applyResult.filePath}`,
612	    }).returning({ id: proposedPatches.id });
613	
614	    const patchId = patchInserted.id;
615	
616	    // 4. Audit log
617	    await db!.insert(governanceAuditLog).values({
618	      action: 'profile_change' as const,
619	      actor: 'auto-apply-pipeline',
620	      reason: `Auto-applied patch #${patchId} for ${violation.violationType} on ${violation.route}`,
621	      metadata: JSON.stringify({
622	        type: 'auto_apply',
623	        patchId,
624	        route: violation.route,
625	        violationType: violation.violationType,
626	        severity: violation.severity,
627	        filePath: applyResult.filePath,
628	        before: applyResult.before.slice(0, 500),
629	        after: applyResult.after.slice(0, 500),
630	        explanation: proposal.explanation,
631	      }),
632	    });
633	
634	    generalLog.info(`[AutoApply] ✅ Patch #${patchId} auto-applied to ${applyResult.filePath}`);
635	
636	    return {
637	      violation,
638	      action: 'auto_applied',
639	      reason: `Successfully applied to ${applyResult.filePath}`,
640	      patchId,
641	      filePath: applyResult.filePath,
642	      diff: { before: applyResult.before, after: applyResult.after },
643	    };
644	  } catch (error) {
645	    generalLog.error(`[AutoApply] Failed for ${violation.route}:`, error);
646	    return {
647	      violation,
648	      action: 'failed',
649	      reason: `Auto-apply error: ${error instanceof Error ? error.message : String(error)}`,
650	    };
651	  }
652	}
653	
654	/**
655	 * Process a batch of violations through the auto-apply pipeline.
656	 * Returns results for each violation.
657	 */
658	export async function processViolationBatchAutoApply(
659	  violations: ViolationInput[],
660	  dryRun: boolean = false,
661	): Promise<AutoApplyResult[]> {
662	  if (violations.length === 0) return [];
663	
664	  generalLog.info(`[AutoApply] Processing batch of ${violations.length} violations (dryRun: ${dryRun})`);
665	
666	  const results: AutoApplyResult[] = [];
667	  for (const violation of violations) {
668	    const result = await processViolationAutoApply(violation, dryRun);
669	    results.push(result);
670	  }
671	
672	  // Notify owner
673	  const autoApplied = results.filter(r => r.action === 'auto_applied');
674	  const queued = results.filter(r => r.action === 'queued_for_review');
675	  const gateBlocked = results.filter(r => r.action === 'buildgate_blocked');
676	  const confidenceGated = results.filter(r => r.action === 'confidence_gated');
677	  const failed = results.filter(r => r.action === 'failed');
678	
679	  if (autoApplied.length > 0 || queued.length > 0 || gateBlocked.length > 0 || confidenceGated.length > 0) {
680	    const lines = [
681	      `Auto-applied: ${autoApplied.length}`,
682	      `Confidence-gated (review required): ${confidenceGated.length}`,
683	      `Queued for review: ${queued.length}`,
684	      `BuildGate blocked: ${gateBlocked.length}`,
685	      `Failed: ${failed.length}`,
686	      '',
687	    ];
688	
689	    if (autoApplied.length > 0) {
690	      lines.push('Auto-applied patches:');
691	      for (const r of autoApplied) {
692	        lines.push(`  • ${r.violation.route}: ${r.violation.violationType} → ${r.filePath}`);
693	      }
694	    }
695	
696	    if (confidenceGated.length > 0) {
697	      lines.push('');
698	      lines.push('Confidence-gated (adaptive autonomy — routed to manual review):');
699	      for (const r of confidenceGated) {
700	        const gate = r.confidenceGate;
701	        lines.push(`  • ${r.violation.route}: ${gate?.recommendation || 'unknown'} (confidence: ${gate?.confidenceScore ?? '?'}/100)`);
702	      }
703	    }
704	
705	    if (gateBlocked.length > 0) {
706	      lines.push('');
707	      lines.push('BuildGate blocked (moved to manual review):');
708	      for (const r of gateBlocked) {
709	        lines.push(`  • ${r.violation.route}: ${r.reason} (${r.buildGateRunId})`);
710	      }
711	    }
712	
713	    if (queued.length > 0) {
714	      lines.push('');
715	      lines.push('Queued for manual review:');
716	      for (const r of queued) {
717	        lines.push(`  • ${r.violation.route}: ${r.reason}`);
718	      }
719	    }
720	
721	    await notifyOwner({
722	      title: `🔧 Auto-Apply Pipeline: ${autoApplied.length} applied, ${confidenceGated.length} confidence-gated, ${gateBlocked.length} gate-blocked, ${queued.length} queued`,
723	      content: lines.join('\n'),
724	    });
725	
726	    // ── Gap 5: Trigger post-fix re-scan if patches were auto-applied ──
727	    if (autoApplied.length > 0 && !dryRun) {
728	      try {
729	        const { triggerPostFixRescan } = await import('../governance/autonomous-loop');
730	        const routes = autoApplied.map(r => r.violation.route);
731	        triggerPostFixRescan(autoApplied.length, routes);
732	        generalLog.info(`[AutoApply] Post-fix re-scan triggered for ${autoApplied.length} applied patches`);
733	      } catch (err) {
734	        generalLog.warn('[AutoApply] Failed to trigger post-fix re-scan (non-fatal):', err);
735	      }
736	    }
737	  }
738	
739	  return results;
740	}
741	
742	
743	// ============================================================================
744	// ONE-CLICK REVERT
745	// ============================================================================
746	
747	export interface RevertResult {
748	  success: boolean;
749	  patchId: number;
750	  route: string;
751	  filePath: string;
752	  error?: string;
753	}
754	
755	/**
756	 * Revert an auto-applied patch by restoring the original content in the source file.
757	 * 
758	 * This is the trust layer: if AI auto-patched something, a human can one-click undo it.
759	 * Every revert is logged in the audit trail.
760	 */
761	export async function revertPatch(
762	  patchId: number,
763	  actor: string,
764	  reason?: string,
765	): Promise<RevertResult> {
766	  const db = getDb();
767	
768	  // 1. Load the patch
769	  const patches = await db!.select().from(proposedPatches).where(eq(proposedPatches.id, patchId)).limit(1);
770	  if (patches.length === 0) {
771	    return { success: false, patchId, route: '', filePath: '', error: 'Patch not found' };
772	  }
773	
774	  const patch = patches[0];
775	
776	  if (patch.status !== 'applied') {
777	    return { success: false, patchId, route: patch.route, filePath: '', error: `Cannot revert: patch status is "${patch.status}" (must be "applied")` };
778	  }
779	
780	  // 2. Find the source file
781	  const relativeFile = ROUTE_TO_FILE[patch.route];
782	  if (!relativeFile) {
783	    return { success: false, patchId, route: patch.route, filePath: '', error: `No source file mapping for route ${patch.route}` };
784	  }
785	
786	  const projectRoot = path.resolve(process.cwd());
787	  const filePath = path.join(projectRoot, relativeFile);
788	
789	  if (!fs.existsSync(filePath)) {
790	    return { success: false, patchId, route: patch.route, filePath: relativeFile, error: `Source file not found: ${relativeFile}` };
791	  }
792	
793	  // 3. Read current file and find the proposed content to revert
794	  const fileContent = fs.readFileSync(filePath, 'utf-8');
795	  const proposedTrimmed = patch.proposedContent.trim();
796	  const originalTrimmed = patch.originalContent.trim();
797	
798	  if (!fileContent.includes(proposedTrimmed)) {
799	    return {
800	      success: false,
801	      patchId,
802	      route: patch.route,
803	      filePath: relativeFile,
804	      error: 'Proposed content not found in current source file. The file may have been modified since the patch was applied.',
805	    };
806	  }
807	
808	  // 4. Replace proposed content with original content
809	  const revertedContent = fileContent.replace(proposedTrimmed, originalTrimmed);
810	  fs.writeFileSync(filePath, revertedContent, 'utf-8');
811	
812	  // 5. Update patch status to "rejected" (reverted)
813	  await db!.update(proposedPatches)
814	    .set({
815	      status: 'rejected',
816	      reviewedBy: actor,
817	      reviewedAt: new Date(),
818	      reviewNote: `REVERTED: ${reason || 'One-click revert by admin'}`,
819	    })
820	    .where(eq(proposedPatches.id, patchId));
821	
822	  // 6. Audit log
823	  await db!.insert(governanceAuditLog).values({
824	    action: 'profile_change' as const,
825	    actor,
826	    reason: `Reverted auto-applied patch #${patchId} on ${patch.route}`,
827	    metadata: JSON.stringify({
828	      type: 'revert',
829	      patchId,
830	      route: patch.route,
831	      violationType: patch.violationType,
832	      severity: patch.severity,
833	      filePath: relativeFile,
834	      before: proposedTrimmed.slice(0, 500),
835	      after: originalTrimmed.slice(0, 500),
836	      revertReason: reason || 'One-click revert by admin',
837	    }),
838	  });
839	
840	  generalLog.info(`[AutoApply] ↩️ Patch #${patchId} REVERTED by ${actor} on ${relativeFile}`);
841	
842	  // 7. Notify owner
843	  await notifyOwner({
844	    title: `↩️ Patch #${patchId} Reverted`,
845	    content: `Patch on ${patch.route} (${patch.violationType}) was reverted by ${actor}.\nReason: ${reason || 'One-click revert'}\nFile: ${relativeFile}`,
846	  });
847	
848	  return {
849	    success: true,
850	    patchId,
851	    route: patch.route,
852	    filePath: relativeFile,
853	  };
854	}
