/**
 * Auto-Apply Pipeline
 * 
 * When auto-apply mode is enabled, this pipeline:
 * 1. Takes violations found by the scanner
 * 2. Generates rewrites via Claude (same as auto-rewrite-pipeline)
 * 3. Applies the fix directly to the source file
 * 4. Logs the full before/after diff to the audit log
 * 5. Notifies the owner of what was changed
 * 
 * SAFETY RAILS:
 * - Only applies to Standard and Enterprise profiles (not Regulated/High-sensitivity)
 * - Only applies patches up to the configured max severity (default: medium)
 * - Critical violations ALWAYS require manual approval regardless of mode
 * - Every auto-applied patch is logged with full diff to governance_audit_log
 * - Profile lock mode disables auto-apply
 * - Dry-run mode available for testing
 */

import * as fs from 'fs';
import * as path from 'path';
import { drizzle } from 'drizzle-orm/postgres-js';
// D-120: shared singleton (was per-call drizzle() — Supabase pool exhaustion).
import { sharedDrizzleDb } from '../_core/db-singleton';
import { eq } from 'drizzle-orm';
import { governanceSettings, governanceAuditLog, proposedPatches, buildGateLog } from '../../drizzle/schema';
import { generateRewrite, processViolation, type ViolationInput, type PatchProposal } from './auto-rewrite-pipeline';
import { notifyOwner } from '../_core/notification';
import { getGravitoMCPServer } from '../agent/mcp/gravito-mcp-server';
import { calculateCorrectionConfidence, type CorrectionConfidence } from '../governance/governance-persistence';
import { generalLog } from '../_core/logger';

function getDb() {
  return sharedDrizzleDb();
}

// ============================================================================
// TYPES
// ============================================================================

export interface AutoApplyConfig {
  enabled: boolean;
  maxSeverity: 'low' | 'medium' | 'high' | 'critical';
  activeProfile: string;
  profileLocked: boolean;
}

/**
 * Confidence-gated auto-apply decision.
 * Maps correction confidence → autonomy level:
 *   auto-fix:     confidence >= 80 → full autonomy
 *   review-first: confidence 50-79 → queue for human review
 *   manual-only:  confidence < 50  → block auto-apply entirely
 */
export interface ConfidenceGateResult {
  allowed: boolean;
  recommendation: CorrectionConfidence['recommendation'];
  confidenceScore: number;
  reason: string;
}

export interface AutoApplyResult {
  violation: ViolationInput;
  action: 'auto_applied' | 'queued_for_review' | 'skipped' | 'failed' | 'buildgate_blocked' | 'confidence_gated';
  reason: string;
  patchId?: number;
  filePath?: string;
  diff?: { before: string; after: string };
  buildGateRunId?: string;
  confidenceGate?: ConfidenceGateResult;
}

// ============================================================================
// BUILD GATE PREFLIGHT — Mandatory architecture + truth check before any rewrite
// ============================================================================

/**
 * Run buildGate preflight check on a proposed rewrite.
 * This ensures every auto-generated patch passes architecture + truth validation
 * BEFORE the rewrite is generated, not after.
 *
 * If buildGate returns 'block' or 'modify', the patch is moved to manual review.
 */
async function runBuildGatePreflight(
  violation: ViolationInput,
): Promise<{ passed: boolean; decision: string; reason: string; runId: string }> {
  try {
    const server = getGravitoMCPServer();
    const result = await server.buildGate({
      proposed_action: 'rewrite_content',
      description: `Auto-rewrite for ${violation.violationType} violation on ${violation.route}: ${violation.violationDetails}`,
      target_module: violation.route,
      claims_in_content: [violation.originalContent],
    });

    // Log the buildGate decision
    try {
      const db = getDb();
      await db!.insert(buildGateLog).values({
        runId: result.gravito_run_id,
        proposedAction: 'rewrite_content',
        description: `Auto-rewrite for ${violation.violationType} on ${violation.route}`,
        targetModule: violation.route,
        decision: result.decision,
        reason: result.reason,
        truthViolations: JSON.stringify(result.truth_violations),
        architectureConflicts: JSON.stringify(result.architecture_conflicts),
        existingTools: JSON.stringify(result.existing_tools),
        existingModules: JSON.stringify(result.existing_modules),
        callerContext: 'auto-apply',
      });
    } catch (logError) {
      generalLog.warn('[BuildGate] Failed to log decision:', logError);
    }

    if (result.decision === 'proceed') {
      generalLog.info(`[BuildGate] ✅ PROCEED for rewrite on ${violation.route} (${result.gravito_run_id})`);
      return { passed: true, decision: result.decision, reason: result.reason, runId: result.gravito_run_id };
    } else {
      generalLog.info(`[BuildGate] ⛔ ${result.decision.toUpperCase()} for rewrite on ${violation.route}: ${result.reason} (${result.gravito_run_id})`);
      return { passed: false, decision: result.decision, reason: result.reason, runId: result.gravito_run_id };
    }
  } catch (error) {
    // BuildGate failure = fail-closed: block the rewrite
    const errorMsg = error instanceof Error ? error.message : String(error);
    generalLog.error(`[BuildGate] ERROR for ${violation.route}: ${errorMsg} — failing closed (blocking rewrite)`);
    return {
      passed: false,
      decision: 'block',
      reason: `BuildGate preflight error: ${errorMsg}`,
      runId: `bg_error_${Date.now()}`,
    };
  }
}

// Severity ordering for comparison
const SEVERITY_ORDER: Record<string, number> = {
  'low': 1,
  'medium': 2,
  'high': 3,
  'critical': 4,
};

// ============================================================================
// CONFIGURATION
// ============================================================================

/**
 * Load auto-apply configuration from the database.
 */
export async function getAutoApplyConfig(): Promise<AutoApplyConfig> {
  try {
    const db = getDb();
    const rows = await db!.select().from(governanceSettings).limit(1);

    if (rows.length === 0) {
      return {
        enabled: false,
        maxSeverity: 'medium',
        activeProfile: 'Enterprise',
        profileLocked: false,
      };
    }

    const settings = rows[0];
    return {
      enabled: settings.autoApplyMode ?? false,
      maxSeverity: (settings.autoApplyMaxSeverity as unknown) ?? 'medium',
      activeProfile: settings.activeProfile,
      profileLocked: settings.profileLocked,
    };
  } catch (error) {
    generalLog.error('[AutoApply] Failed to load config:', error);
    return {
      enabled: false,
      maxSeverity: 'medium',
      activeProfile: 'Enterprise',
      profileLocked: false,
    };
  }
}

/**
 * Update auto-apply settings in the database.
 */
export async function setAutoApplyMode(
  enabled: boolean,
  maxSeverity?: 'low' | 'medium' | 'high' | 'critical',
  actor?: string,
): Promise<void> {
  const db = getDb();
  const rows = await db!.select().from(governanceSettings).limit(1);

  const updateData: any = {
    autoApplyMode: enabled,
    lastUpdatedBy: actor || 'system',
    lastUpdatedAt: new Date(),
  };
  if (maxSeverity) {
    updateData.autoApplyMaxSeverity = maxSeverity;
  }

  if (rows.length === 0) {
    await db!.insert(governanceSettings).values({
      ...updateData,
      activeProfile: 'Enterprise',
    });
  } else {
    await db!.update(governanceSettings)
      .set(updateData)
      .where(eq(governanceSettings.id, rows[0].id));
  }

  // Audit log
  await db!.insert(governanceAuditLog).values({
    action: 'profile_change' as const,
    actor: actor || 'system',
    reason: `Auto-apply mode ${enabled ? 'ENABLED' : 'DISABLED'}${maxSeverity ? ` (max severity: ${maxSeverity})` : ''}`,
    metadata: JSON.stringify({ autoApplyMode: enabled, maxSeverity }),
  });

  generalLog.info(`[AutoApply] Mode ${enabled ? 'ENABLED' : 'DISABLED'} by ${actor || 'system'}`);
}

// ============================================================================
// SAFETY CHECKS
// ============================================================================

/**
 * Determine if a violation can be auto-applied based on current config.
 * Static safety checks only — does not consult historical confidence.
 */
function canAutoApplyStatic(
  violation: ViolationInput,
  config: AutoApplyConfig,
): { allowed: boolean; reason: string } {
  // Check 1: Auto-apply must be enabled
  if (!config.enabled) {
    return { allowed: false, reason: 'Auto-apply mode is disabled' };
  }

  // Check 2: Profile lock disables auto-apply
  if (config.profileLocked) {
    return { allowed: false, reason: 'Profile is locked — auto-apply disabled during lock' };
  }

  // Check 3: Only Standard and Enterprise profiles allow auto-apply
  if (!['Standard', 'Enterprise'].includes(config.activeProfile)) {
    return { allowed: false, reason: `Auto-apply not allowed for ${config.activeProfile} profile (requires manual approval)` };
  }

  // Check 4: Critical violations ALWAYS require manual approval
  if (violation.severity === 'critical') {
    return { allowed: false, reason: 'Critical violations always require manual approval' };
  }

  // Check 5: Severity must be within configured max
  const violationLevel = SEVERITY_ORDER[violation.severity] || 0;
  const maxLevel = SEVERITY_ORDER[config.maxSeverity] || 2;
  if (violationLevel > maxLevel) {
    return { allowed: false, reason: `Violation severity ${violation.severity} exceeds auto-apply max ${config.maxSeverity}` };
  }

  return { allowed: true, reason: 'Passed all static safety checks' };
}

/**
 * Check correction confidence for a route — adaptive autonomy gating.
 * 
 * This is the key innovation: instead of a global on/off for auto-apply,
 * each route gets its own autonomy level based on historical fix patterns.
 * 
 * Routes where fixes reliably stick → auto-fix allowed
 * Routes where fixes sometimes revert → queue for human review
 * Routes where fixes frequently fail → block auto-apply entirely
 * 
 * Falls back gracefully: if confidence data is unavailable, allows
 * auto-apply (the static checks already passed).
 */
async function checkCorrectionConfidenceGate(
  route: string,
): Promise<ConfidenceGateResult> {
  try {
    const confidence = await calculateCorrectionConfidence(route);

    // No correction history yet → allow (benefit of the doubt)
    if (confidence.totalCorrections === 0) {
      return {
        allowed: true,
        recommendation: 'review-first',
        confidenceScore: confidence.confidenceScore,
        reason: `No correction history for ${route} — allowing with default confidence`,
      };
    }

    switch (confidence.recommendation) {
      case 'auto-fix':
        return {
          allowed: true,
          recommendation: 'auto-fix',
          confidenceScore: confidence.confidenceScore,
          reason: `High correction confidence (${confidence.confidenceScore}/100) — ${confidence.successfulCorrections}/${confidence.totalCorrections} fixes stuck`,
        };

      case 'review-first':
        return {
          allowed: false,
          recommendation: 'review-first',
          confidenceScore: confidence.confidenceScore,
          reason: `Medium correction confidence (${confidence.confidenceScore}/100) — ${confidence.revertedCorrections}/${confidence.totalCorrections} fixes reverted. Routing to manual review.`,
        };

      case 'manual-only':
        return {
          allowed: false,
          recommendation: 'manual-only',
          confidenceScore: confidence.confidenceScore,
          reason: `Low correction confidence (${confidence.confidenceScore}/100) — fixes frequently revert on ${route}. Auto-apply blocked.`,
        };

      default:
        return {
          allowed: true,
          recommendation: 'review-first',
          confidenceScore: confidence.confidenceScore,
          reason: 'Unknown recommendation — allowing with caution',
        };
    }
  } catch (err) {
    // Confidence check failed — graceful degradation: allow auto-apply
    generalLog.warn(`[AutoApply] Correction confidence check failed for ${route}:`, err);
    return {
      allowed: true,
      recommendation: 'review-first',
      confidenceScore: 50,
      reason: 'Correction confidence unavailable — allowing with default (graceful degradation)',
    };
  }
}

/**
 * Combined auto-apply decision: static checks + confidence gating.
 * 
 * Two-layer safety:
 * 1. Static checks (config, profile, severity) — fast, deterministic
 * 2. Confidence gate (historical patterns) — adaptive, per-route
 * 
 * Both must pass for auto-apply to proceed.
 */
async function canAutoApply(
  violation: ViolationInput,
  config: AutoApplyConfig,
): Promise<{ allowed: boolean; reason: string; confidenceGate?: ConfidenceGateResult }> {
  // Layer 1: Static safety checks
  const staticResult = canAutoApplyStatic(violation, config);
  if (!staticResult.allowed) {
    return { allowed: false, reason: staticResult.reason };
  }

  // Layer 2: Correction confidence gating (adaptive autonomy)
  const confidenceGate = await checkCorrectionConfidenceGate(violation.route);

  if (!confidenceGate.allowed) {
    generalLog.info(`[AutoApply] ${violation.route}: Static checks passed but confidence gate blocked — ${confidenceGate.reason}`);
    return {
      allowed: false,
      reason: `Confidence gate: ${confidenceGate.reason}`,
      confidenceGate,
    };
  }

  generalLog.info(`[AutoApply] ${violation.route}: All checks passed (confidence: ${confidenceGate.confidenceScore}/100, recommendation: ${confidenceGate.recommendation})`);
  return {
    allowed: true,
    reason: `${staticResult.reason} + ${confidenceGate.reason}`,
    confidenceGate,
  };
}

// ============================================================================
// SOURCE FILE MAPPING
// ============================================================================

const ROUTE_TO_FILE: Record<string, string> = {
  '/': 'client/src/pages/Home.tsx',
  '/products': 'client/src/pages/Products.tsx',
  '/pricing': 'client/src/pages/Pricing.tsx',
  '/products/flux': 'client/src/pages/products/Flux.tsx',
  '/products/sentinel': 'client/src/pages/products/Sentinel.tsx',
  '/products/conduit': 'client/src/pages/products/Conduit.tsx',
  '/products/deploy': 'client/src/pages/products/Deploy.tsx',
  '/products/certify': 'client/src/pages/products/Certify.tsx',
  '/for-cto': 'client/src/pages/ForCTO.tsx',
  '/for-cs-director': 'client/src/pages/ForCSDirector.tsx',
  '/for-ceo': 'client/src/pages/ForCEO.tsx',
  '/healthcare': 'client/src/pages/Healthcare.tsx',
  '/finance': 'client/src/pages/Finance.tsx',
  '/trust': 'client/src/pages/Trust.tsx',
  '/security': 'client/src/pages/Security.tsx',
  '/proof': 'client/src/pages/ProofArtifacts.tsx',
};

/**
 * Apply a rewrite to the actual source file.
 * Returns the file path and before/after diff.
 */
function applyToSourceFile(
  route: string,
  originalContent: string,
  proposedContent: string,
): { success: boolean; filePath: string; before: string; after: string; error?: string } {
  const relativeFile = ROUTE_TO_FILE[route];
  if (!relativeFile) {
    return {
      success: false,
      filePath: '',
      before: '',
      after: '',
      error: `No source file mapping for route ${route}`,
    };
  }

  const projectRoot = path.resolve(process.cwd());
  const filePath = path.join(projectRoot, relativeFile);

  if (!fs.existsSync(filePath)) {
    return {
      success: false,
      filePath: relativeFile,
      before: '',
      after: '',
      error: `Source file not found: ${relativeFile}`,
    };
  }

  const fileContent = fs.readFileSync(filePath, 'utf-8');

  // Find the original content in the file (fuzzy match — content may be extracted/transformed)
  // We look for the longest substring match
  const normalizedOriginal = originalContent.trim().replace(/\s+/g, ' ');
  const normalizedFile = fileContent.replace(/\s+/g, ' ');

  // Try exact match first
  if (fileContent.includes(originalContent.trim())) {
    const newContent = fileContent.replace(originalContent.trim(), proposedContent.trim());
    fs.writeFileSync(filePath, newContent, 'utf-8');
    return {
      success: true,
      filePath: relativeFile,
      before: originalContent.trim(),
      after: proposedContent.trim(),
    };
  }

  // Try normalized match (whitespace-insensitive)
  if (normalizedFile.includes(normalizedOriginal)) {
    // Find the actual position in the original file
    const startIdx = normalizedFile.indexOf(normalizedOriginal);
    // Map back to original file positions (approximate)
    let charCount = 0;
    let realStart = 0;
    for (let i = 0; i < fileContent.length; i++) {
      if (charCount === startIdx) {
        realStart = i;
        break;
      }
      charCount++;
      // Skip extra whitespace
      while (i + 1 < fileContent.length && /\s/.test(fileContent[i]) && /\s/.test(fileContent[i + 1])) {
        i++;
      }
    }

    // For safety, log but don't apply fuzzy matches
    generalLog.warn(`[AutoApply] Fuzzy match found for ${route} but not applying (safety). Queuing for manual review.`);
    return {
      success: false,
      filePath: relativeFile,
      before: originalContent.trim(),
      after: proposedContent.trim(),
      error: 'Only exact matches are auto-applied. Fuzzy match found — queued for manual review.',
    };
  }

  return {
    success: false,
    filePath: relativeFile,
    before: originalContent.trim(),
    after: proposedContent.trim(),
    error: 'Original content not found in source file. Content may have been extracted/transformed during scanning.',
  };
}

// ============================================================================
// MAIN PIPELINE
// ============================================================================

/**
 * Process a violation through the auto-apply pipeline.
 * 
 * If auto-apply is allowed: generate rewrite → apply to source → log audit
 * If not allowed: fall back to the standard approval queue
 */
export async function processViolationAutoApply(
  violation: ViolationInput,
  dryRun: boolean = false,
): Promise<AutoApplyResult> {
  const config = await getAutoApplyConfig();
  const safety = await canAutoApply(violation, config);

  if (!safety.allowed) {
    // Determine if this was blocked by confidence gate vs static checks
    const isConfidenceGated = safety.confidenceGate && !safety.confidenceGate.allowed;
    const action = isConfidenceGated ? 'confidence_gated' as const : 'queued_for_review' as const;

    generalLog.info(`[AutoApply] ${violation.route}: ${safety.reason} — ${isConfidenceGated ? 'confidence-gated' : 'queuing'} for manual review`);
    try {
      const patchId = await processViolation(violation);
      return {
        violation,
        action,
        reason: safety.reason,
        patchId,
        confidenceGate: safety.confidenceGate,
      };
    } catch (error) {
      return {
        violation,
        action: 'failed',
        reason: `Queue failed: ${error instanceof Error ? error.message : String(error)}`,
        confidenceGate: safety.confidenceGate,
      };
    }
  }

  // Auto-apply path
  generalLog.info(`[AutoApply] ${violation.route}: Running buildGate preflight for ${violation.violationType}`);

  try {
    // 0. BUILD GATE PREFLIGHT — mandatory architecture + truth check
    const gateResult = await runBuildGatePreflight(violation);
    if (!gateResult.passed) {
      generalLog.info(`[AutoApply] ${violation.route}: BuildGate ${gateResult.decision} — ${gateResult.reason}. Moving to manual review.`);
      try {
        const patchId = await processViolation(violation);
        return {
          violation,
          action: 'buildgate_blocked',
          reason: `BuildGate ${gateResult.decision}: ${gateResult.reason}`,
          patchId,
          buildGateRunId: gateResult.runId,
        };
      } catch (queueError) {
        return {
          violation,
          action: 'buildgate_blocked',
          reason: `BuildGate ${gateResult.decision}: ${gateResult.reason} (queue also failed: ${queueError instanceof Error ? queueError.message : String(queueError)})`,
          buildGateRunId: gateResult.runId,
        };
      }
    }

    generalLog.info(`[AutoApply] ${violation.route}: BuildGate passed (${gateResult.runId}). Generating rewrite for ${violation.violationType}`);

    // 1. Generate rewrite
    const proposal = await generateRewrite(violation);

    if (dryRun) {
      return {
        violation,
        action: 'skipped',
        reason: 'Dry run — rewrite generated but not applied',
        diff: { before: violation.originalContent, after: proposal.proposedContent },
      };
    }

    // 2. Apply to source file
    const applyResult = applyToSourceFile(
      violation.route,
      violation.originalContent,
      proposal.proposedContent,
    );

    if (!applyResult.success) {
      // Couldn't apply — fall back to queue
      generalLog.warn(`[AutoApply] ${violation.route}: Apply failed — ${applyResult.error}. Queuing for manual review.`);
      const patchId = await processViolation(violation);
      return {
        violation,
        action: 'queued_for_review',
        reason: `Auto-apply failed: ${applyResult.error}`,
        patchId,
        filePath: applyResult.filePath,
        diff: { before: applyResult.before, after: applyResult.after },
      };
    }

    // 3. Store as applied patch
    const db = getDb();
    const [patchInserted] = await db!.insert(proposedPatches).values({
      scanId: violation.scanId,
      route: violation.route,
      violationType: violation.violationType,
      severity: violation.severity,
      originalContent: violation.originalContent,
      proposedContent: proposal.proposedContent,
      explanation: `[AUTO-APPLIED] ${proposal.explanation}`,
      status: 'applied',
      reviewedBy: 'auto-apply-pipeline',
      reviewedAt: new Date(),
      reviewNote: `Auto-applied by governance pipeline. File: ${applyResult.filePath}`,
    }).returning({ id: proposedPatches.id });

    const patchId = patchInserted.id;

    // 4. Audit log
    await db!.insert(governanceAuditLog).values({
      action: 'profile_change' as const,
      actor: 'auto-apply-pipeline',
      reason: `Auto-applied patch #${patchId} for ${violation.violationType} on ${violation.route}`,
      metadata: JSON.stringify({
        type: 'auto_apply',
        patchId,
        route: violation.route,
        violationType: violation.violationType,
        severity: violation.severity,
        filePath: applyResult.filePath,
        before: applyResult.before.slice(0, 500),
        after: applyResult.after.slice(0, 500),
        explanation: proposal.explanation,
      }),
    });

    generalLog.info(`[AutoApply] ✅ Patch #${patchId} auto-applied to ${applyResult.filePath}`);

    return {
      violation,
      action: 'auto_applied',
      reason: `Successfully applied to ${applyResult.filePath}`,
      patchId,
      filePath: applyResult.filePath,
      diff: { before: applyResult.before, after: applyResult.after },
    };
  } catch (error) {
    generalLog.error(`[AutoApply] Failed for ${violation.route}:`, error);
    return {
      violation,
      action: 'failed',
      reason: `Auto-apply error: ${error instanceof Error ? error.message : String(error)}`,
    };
  }
}

/**
 * Process a batch of violations through the auto-apply pipeline.
 * Returns results for each violation.
 */
export async function processViolationBatchAutoApply(
  violations: ViolationInput[],
  dryRun: boolean = false,
): Promise<AutoApplyResult[]> {
  if (violations.length === 0) return [];

  generalLog.info(`[AutoApply] Processing batch of ${violations.length} violations (dryRun: ${dryRun})`);

  const results: AutoApplyResult[] = [];
  for (const violation of violations) {
    const result = await processViolationAutoApply(violation, dryRun);
    results.push(result);
  }

  // Notify owner
  const autoApplied = results.filter(r => r.action === 'auto_applied');
  const queued = results.filter(r => r.action === 'queued_for_review');
  const gateBlocked = results.filter(r => r.action === 'buildgate_blocked');
  const confidenceGated = results.filter(r => r.action === 'confidence_gated');
  const failed = results.filter(r => r.action === 'failed');

  if (autoApplied.length > 0 || queued.length > 0 || gateBlocked.length > 0 || confidenceGated.length > 0) {
    const lines = [
      `Auto-applied: ${autoApplied.length}`,
      `Confidence-gated (review required): ${confidenceGated.length}`,
      `Queued for review: ${queued.length}`,
      `BuildGate blocked: ${gateBlocked.length}`,
      `Failed: ${failed.length}`,
      '',
    ];

    if (autoApplied.length > 0) {
      lines.push('Auto-applied patches:');
      for (const r of autoApplied) {
        lines.push(`  • ${r.violation.route}: ${r.violation.violationType} → ${r.filePath}`);
      }
    }

    if (confidenceGated.length > 0) {
      lines.push('');
      lines.push('Confidence-gated (adaptive autonomy — routed to manual review):');
      for (const r of confidenceGated) {
        const gate = r.confidenceGate;
        lines.push(`  • ${r.violation.route}: ${gate?.recommendation || 'unknown'} (confidence: ${gate?.confidenceScore ?? '?'}/100)`);
      }
    }

    if (gateBlocked.length > 0) {
      lines.push('');
      lines.push('BuildGate blocked (moved to manual review):');
      for (const r of gateBlocked) {
        lines.push(`  • ${r.violation.route}: ${r.reason} (${r.buildGateRunId})`);
      }
    }

    if (queued.length > 0) {
      lines.push('');
      lines.push('Queued for manual review:');
      for (const r of queued) {
        lines.push(`  • ${r.violation.route}: ${r.reason}`);
      }
    }

    await notifyOwner({
      title: `🔧 Auto-Apply Pipeline: ${autoApplied.length} applied, ${confidenceGated.length} confidence-gated, ${gateBlocked.length} gate-blocked, ${queued.length} queued`,
      content: lines.join('\n'),
    });

    // ── Gap 5: Trigger post-fix re-scan if patches were auto-applied ──
    if (autoApplied.length > 0 && !dryRun) {
      try {
        const { triggerPostFixRescan } = await import('../governance/autonomous-loop');
        const routes = autoApplied.map(r => r.violation.route);
        triggerPostFixRescan(autoApplied.length, routes);
        generalLog.info(`[AutoApply] Post-fix re-scan triggered for ${autoApplied.length} applied patches`);
      } catch (err) {
        generalLog.warn('[AutoApply] Failed to trigger post-fix re-scan (non-fatal):', err);
      }
    }
  }

  return results;
}


// ============================================================================
// ONE-CLICK REVERT
// ============================================================================

export interface RevertResult {
  success: boolean;
  patchId: number;
  route: string;
  filePath: string;
  error?: string;
}

/**
 * Revert an auto-applied patch by restoring the original content in the source file.
 * 
 * This is the trust layer: if AI auto-patched something, a human can one-click undo it.
 * Every revert is logged in the audit trail.
 */
export async function revertPatch(
  patchId: number,
  actor: string,
  reason?: string,
): Promise<RevertResult> {
  const db = getDb();

  // 1. Load the patch
  const patches = await db!.select().from(proposedPatches).where(eq(proposedPatches.id, patchId)).limit(1);
  if (patches.length === 0) {
    return { success: false, patchId, route: '', filePath: '', error: 'Patch not found' };
  }

  const patch = patches[0];

  if (patch.status !== 'applied') {
    return { success: false, patchId, route: patch.route, filePath: '', error: `Cannot revert: patch status is "${patch.status}" (must be "applied")` };
  }

  // 2. Find the source file
  const relativeFile = ROUTE_TO_FILE[patch.route];
  if (!relativeFile) {
    return { success: false, patchId, route: patch.route, filePath: '', error: `No source file mapping for route ${patch.route}` };
  }

  const projectRoot = path.resolve(process.cwd());
  const filePath = path.join(projectRoot, relativeFile);

  if (!fs.existsSync(filePath)) {
    return { success: false, patchId, route: patch.route, filePath: relativeFile, error: `Source file not found: ${relativeFile}` };
  }

  // 3. Read current file and find the proposed content to revert
  const fileContent = fs.readFileSync(filePath, 'utf-8');
  const proposedTrimmed = patch.proposedContent.trim();
  const originalTrimmed = patch.originalContent.trim();

  if (!fileContent.includes(proposedTrimmed)) {
    return {
      success: false,
      patchId,
      route: patch.route,
      filePath: relativeFile,
      error: 'Proposed content not found in current source file. The file may have been modified since the patch was applied.',
    };
  }

  // 4. Replace proposed content with original content
  const revertedContent = fileContent.replace(proposedTrimmed, originalTrimmed);
  fs.writeFileSync(filePath, revertedContent, 'utf-8');

  // 5. Update patch status to "rejected" (reverted)
  await db!.update(proposedPatches)
    .set({
      status: 'rejected',
      reviewedBy: actor,
      reviewedAt: new Date(),
      reviewNote: `REVERTED: ${reason || 'One-click revert by admin'}`,
    })
    .where(eq(proposedPatches.id, patchId));

  // 6. Audit log
  await db!.insert(governanceAuditLog).values({
    action: 'profile_change' as const,
    actor,
    reason: `Reverted auto-applied patch #${patchId} on ${patch.route}`,
    metadata: JSON.stringify({
      type: 'revert',
      patchId,
      route: patch.route,
      violationType: patch.violationType,
      severity: patch.severity,
      filePath: relativeFile,
      before: proposedTrimmed.slice(0, 500),
      after: originalTrimmed.slice(0, 500),
      revertReason: reason || 'One-click revert by admin',
    }),
  });

  generalLog.info(`[AutoApply] ↩️ Patch #${patchId} REVERTED by ${actor} on ${relativeFile}`);

  // 7. Notify owner
  await notifyOwner({
    title: `↩️ Patch #${patchId} Reverted`,
    content: `Patch on ${patch.route} (${patch.violationType}) was reverted by ${actor}.\nReason: ${reason || 'One-click revert'}\nFile: ${relativeFile}`,
  });

  return {
    success: true,
    patchId,
    route: patch.route,
    filePath: relativeFile,
  };
}

